// soundpass.js - tiny Web Audio player for packs generated by soundpass. No dependencies.
//
// Setup: render the pack into a folder your game serves statically (e.g. public/sfx).
// Usage:
//   import { SoundPass } from './soundpass.js';
//   const sfx = new SoundPass('sfx/');
//   await sfx.load();                 // fetch + decode everything
//   sfx.play('coin');
//   sfx.play('combo', { level: combo - 1 });
//   sfx.volume = 0.8; sfx.muted = true;
//
// Browsers only start audio after a user gesture; play() resumes the context for you,
// so the first sound must come from a click / key / touch handler.

export class SoundPass {
  constructor(base = 'sfx/', { context } = {}) {
    this.base = base.endsWith('/') ? base : base + '/';
    this.ctx = context || new (window.AudioContext || window.webkitAudioContext)();
    this.out = this.ctx.createGain();
    this.out.connect(this.ctx.destination);
    this.sounds = new Map();
    this.lastVariant = new Map();
    this.lastPlayed = new Map();
    this.muted = false;
    this._volume = 1;
  }

  get volume() { return this._volume; }
  set volume(v) { this._volume = Math.max(0, Math.min(1, v)); this.out.gain.value = this._volume; }

  async load() {
    const res = await fetch(this.base + 'manifest.json');
    if (!res.ok) throw new Error('soundpass: manifest.json not found at ' + this.base);
    const manifest = await res.json();
    await Promise.all(manifest.sounds.map(async (s) => {
      const buffers = await Promise.all(s.files.map(async (f) => {
        const data = await (await fetch(this.base + f)).arrayBuffer();
        return await new Promise((ok, err) => this.ctx.decodeAudioData(data, ok, err));
      }));
      this.sounds.set(s.id, { buffers, ladder: !!s.ladder });
    }));
    return this;
  }

  has(id) { return this.sounds.has(id); }

  play(id, { level = 0, volume = 1, pitchJitter = 0.03 } = {}) {
    if (this.muted) return;
    const s = this.sounds.get(id);
    if (!s) { console.warn('soundpass: no sound "' + id + '"'); return; }
    if (this.ctx.state === 'suspended') this.ctx.resume();

    const now = this.ctx.currentTime;
    if (now - (this.lastPlayed.get(id) ?? -1) < 0.03) return;
    this.lastPlayed.set(id, now);

    let i;
    if (s.ladder) {
      i = Math.max(0, Math.min(s.buffers.length - 1, level));
    } else {
      i = Math.floor(Math.random() * s.buffers.length);
      if (s.buffers.length > 1 && this.lastVariant.get(id) === i) i = (i + 1) % s.buffers.length;
      this.lastVariant.set(id, i);
    }
    const src = this.ctx.createBufferSource();
    src.buffer = s.buffers[i];
    if (!s.ladder) src.playbackRate.value = 1 + (Math.random() * 2 - 1) * pitchJitter;
    const g = this.ctx.createGain();
    g.gain.value = volume;
    src.connect(g).connect(this.out);
    src.start();
    return src;
  }
}
